    let ch: Vec<char> = s.chars().filter(|c| c.is_alphanumeric())
        .map(|c| c.to_lowercase().next().unwrap()).collect();
    let (mut l, mut r) = (0, ch.len().saturating_sub(1));
    while l < r {
        if ch[l] != ch[r] { return false; }
        l += 1; r -= 1;
    }
    true
}

