use std::collections::HashSet;

// Safe Rust cannot build a cycle out of Option<Box<ListNode>>, so this
// mirrors the Floyd intent by walking the list and recording visited nodes
// by raw pointer; a repeat means a cycle.
fn has_cycle(head: Option<Box<ListNode>>) -> bool {
    let mut seen: HashSet<*const ListNode> = HashSet::new();
    let mut curr = head.as_deref();
    while let Some(node) = curr {
        let ptr = node as *const ListNode;
        if !seen.insert(ptr) {
            return true;
        }
        curr = node.next.as_deref();
    }
    false
}

