fn is_valid_bst(root: Option<Rc<RefCell<TreeNode>>>) -> bool {
    fn check(n: &Option<Rc<RefCell<TreeNode>>>, lo: i64, hi: i64) -> bool {
        match n {
            None => true,
            Some(node) => {
                let v = node.borrow().val as i64;
                v > lo && v < hi
                    && check(&node.borrow().left, lo, v)
                    && check(&node.borrow().right, v, hi)
            }
        }
    }
    check(&root, i64::MIN, i64::MAX)
}

