    let mut res = vec![];
    fn bt(path: &mut Vec<i32>, rem: &[i32], res: &mut Vec<Vec<i32>>) {
        if rem.is_empty() { res.push(path.clone()); return; }
        for i in 0..rem.len() {
            path.push(rem[i]);
            let nr: Vec<i32> = rem.iter().enumerate()
                .filter(|&(j,_)| j!=i).map(|(_,&v)| v).collect();
            bt(path, &nr, res);
            path.pop();
        }
    }
